using System;using System.Collections.Generic;using System.Linq;
namespace Exoduser.UnityPort.Core {
 public sealed class ForgePoint {public double x,y,score,a;}
 public sealed class ForgeReserved {public double l,t,r,b;}
 public sealed class ForgeSlots {public List<ForgePoint> L=new List<ForgePoint>(),R=new List<ForgePoint>(),M=new List<ForgePoint>();public double dx,dy,Lw,lg;public int Count=>L.Count+R.Count+M.Count;}
 public sealed class SkillForgeGeometry {
  public double cx,cy,R,nodeSize,W,H,discR,coreR;public static SkillForgeGeometry Build(double width,double height,int setCount,double wheelK=1){var g=new SkillForgeGeometry{W=width,H=height};double usable=Math.Max(160,height-10-78);g.cx=width/2;int cnt=Math.Max(1,setCount+1);g.R=Math.Max(56,Math.Min(width*.19,usable*.27)*wheelK);g.nodeSize=Math.Max(30,Math.Min(84,Math.Min(g.R*.56,2*Math.PI*g.R/cnt*.72)));g.discR=Math.Max(g.R*1.32,g.R+g.nodeSize/2*1.3);g.cy=Math.Max(10+g.discR,10+usable-g.discR-4);g.coreR=Math.Max(48,Math.Min(150,Math.Min(g.R*1.02,(g.R-g.nodeSize/2)*1.3)))/2;return g;}
  static double Hypot(double x,double y)=>Math.Sqrt(x*x+y*y);public static double Amp(double o)=>Math.Min(1,Math.Max(.5,o/52));
  public static ForgePoint[] Sockets(int n,double radius){var p=new ForgePoint[n];for(int i=0;i<n;i++){double a=-Math.PI/2+i*2*Math.PI/n;p[i]=new ForgePoint{x=Math.Cos(a)*radius,y=Math.Sin(a)*radius,a=a};}return p;}
  public ForgeSlots Slots(double o,IEnumerable<ForgeReserved> reserved,double k=1,bool compact=false){var rs=(reserved??new ForgeReserved[0]).ToArray();double A=Amp(o),up=10.2*A,lg=Math.Floor(up+3+.5),TOP=up+3,LB=lg+(compact?15:29),dx=Math.Max(o*1.62,o+40)*k,dy=(o+LB+up+3)*k,Lw=Math.Min(2*dx-o-10-14*A,Math.Min(2*dx-44,136)),ex=discR+o/2+12;var output=new ForgeSlots{dx=dx,dy=dy,Lw=Lw,lg=lg};for(int j=-40;j<=40;j++){double x=cx+j*dx;if(x-Lw/2<2||x+Lw/2>W-2)continue;double off=Math.Abs(j)%2==1?dy/2:0;for(int i=-40;i<=40;i++){double y=cy+i*dy+off;if(y-o/2-TOP<2||y+o/2+LB>H-2)continue;if(Hypot(x-cx,y-cy)<ex+up)continue;double lt=y+o/2+2,lb=y+o/2+LB,ddx=Math.Max(x-Lw/2-cx,Math.Max(0,cx-x-Lw/2)),ddy=Math.Max(lt-cy,Math.Max(0,cy-lb));if(Hypot(ddx,ddy)<discR+6)continue;if(rs.Any(r=>x-Lw/2<r.r&&x+Lw/2>r.l&&y-o/2-TOP<r.b&&y+o/2+LB>r.t))continue;double d=Hypot(x-cx,y-cy),ang=Math.Atan2(y-cy,Math.Abs(x-cx)==0?1:Math.Abs(x-cx));(j<0?output.L:j>0?output.R:output.M).Add(new ForgePoint{x=x,y=y,score=d+Math.Abs(ang+.35)*dy*.55});}}output.L=output.L.OrderBy(p=>p.score).ToList();output.R=output.R.OrderBy(p=>p.score).ToList();output.M=output.M.OrderBy(p=>p.score).ToList();return output;}
  public ForgeSlots Fit(int count,IEnumerable<ForgeReserved> reserved,out double size,out bool compact){double max=Math.Max(34,Math.Min(58,Math.Min(H*.088,W*.052)));size=max;compact=false;ForgeSlots slots=null;bool found=false;foreach(bool cp in new[]{false,true}){size=max;double min=cp?28:34;for(int pass=0;pass<24;pass++){slots=Slots(size,reserved,1,cp);if(slots.Count>=count){compact=cp;found=true;break;}if(size<=min)break;size=Math.Max(min,size*.95);}if(found)break;}if(slots.Count>=count)foreach(double k in new[]{1.6,1.5,1.42,1.34,1.26,1.18,1.1}){var s=Slots(size,reserved,k,compact);if(s.Count>=count){slots=s;break;}}return slots;}
 }
}
